{
  "name": "opencode-launchpad",
  "version": "0.1.3",
  "description": "OpenCode TUI plugin: project runner buttons, reviewed commit and push flows, and a live log dialog in the session sidebar.",
  "type": "module",
  "license": "MIT",
  "author": "giannisCKS",
  "homepage": "https://github.com/giannisCKS/opencode-launchpad#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/giannisCKS/opencode-launchpad.git"
  },
  "bugs": {
    "url": "https://github.com/giannisCKS/opencode-launchpad/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "plugin"
  ],
  "main": "./tui.js",
  "exports": {
    ".": "./tui.js",
    "./tui": "./tui.js",
    "./package.json": "./package.json"
  },
  "files": [
    "tui.js",
    "runners.js",
    "git.js",
    "git-detection.js",
    "visibility.js",
    "button-config.js",
    "view.jsx",
    "view.js",
    "build-view.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node build-view.js",
    "prepack": "npm run build",
    "test": "node --test"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@opentui/solid": "0.6.6"
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "babel-preset-solid": "1.9.12"
  },
  "peerDependencies": {
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "solid-js": {
      "optional": true
    }
  }
}
